 38	uint8_t g_function(uint8_t a, uint8_t b, uint8_t x) {
 39	    uint8_t temp = (a + b + x) & 0xFF;  // Keep it as 8-bit
 40	    return ((temp << 2) | (temp >> 6)) & 0xFF;
