 44	uint32_t f_function(uint32_t input_val) {
 45	    uint8_t x[4];
 46	    uint8_t y[4];
 47	    
 48	    // Extract bytes from input (big-endian)
 49	    for (int i = 0; i < 4; i++) {
 50	        x[i] = input_val & 0xFF;
 51	        input_val >>= 8;
 52	    }
 53	    
 54	    // Apply G function operations
 55	    y[2] = g_function(x[3] ^ x[2], x[1] ^ x[0], 1);
 56	    y[3] = g_function(x[3], y[2], 0);
 57	    y[1] = g_function(x[1] ^ x[0], y[2], 0);
 58	    y[0] = g_function(x[0], y[1], 1);
 59	    
 60	    // Combine bytes into output (big-endian)
 61	    uint32_t output = 0;
 62	    for (int i = 0; i < 4; i++) {
 63	        output |= (uint32_t)y[i] << (8 * i);
 64	    }
 65	    
 66	    return output & 0xFFFFFFFF;
 67	}
